    표8_상담적용: [
        {"상황":"가족 중 믿지 않는 사람 때문에 아파하는 성도", "성경원리":"예수님의 형제 야고보도 처음에는 믿지 않았다. 그러나 부활하신 주님을 만나 변화되었다. 포기하지 말라", "실제적용":"고전 15:7을 함께 읽고 야고보의 변화를 나눈다. 믿지 않는 가족을 위해 계속 기도하고 삶으로 복음을 보여주도록 격려한다"},
        {"상황":"교회 내 지도력 갈등으로 어려운 공동체", "성경원리":"베드로와 야고보가 다른 배경이지만 함께 협력했다. 다양한 지도자들의 협력이 건강한 교회를 만든다", "실제적용":"갈 2:9를 함께 읽고 초대 교회가 어떻게 다양성 속에서 연합을 이루었는지 나눈다. 서로의 역할을 존중하고 공통된 복음 위에서 협력하도록 돕는다"},
        {"상황":"복음의 사실성을 의심하는 성도", "성경원리":"주의 형제 야고보의 회심이 부활의 증거이다. 가장 가까이서 함께 자란 형제가 믿게 된 것은 실제 부활이 있었음을 강력히 증거한다", "실제적용":"고전 15:3-8의 부활 증인 목록을 함께 살펴보고 야고보의 증거가 왜 특별히 강력한 증거인지 나눈다"}
    ],
    표9_교차참조: [
        {"구절":"고전 15:7", "연결점":"그 후에 야고보에게 보이셨으며 그 후에 모든 사도에게 보이셨고 - 부활하신 주님이 야고보에게 나타나심", "구분":"신약"},
        {"구절":"요 7:5", "연결점":"이는 그 형제들도 예수를 믿지 아니함이러라 - 야고보의 회심 전 불신", "구분":"신약"},
        {"구절":"마 13:55", "연결점":"이는 그 목수의 아들이 아니냐 그 모친은 마리아, 그 형제들은 야고보 요셉 시몬 유다가 아니냐 - 야고보를 예수님의 형제로 확인", "구분":"신약"},
        {"구절":"행 15:13-21", "연결점":"침묵하고 야고보가 말하되 - 예루살렘 공의회에서 야고보의 지도자 역할", "구분":"신약"},
        {"구절":"약 1:1", "연결점":"하나님과 주 예수 그리스도의 종 야고보는 - 야고보가 예수님의 종으로 자신을 소개", "구분":"신약"},
        {"구절":"갈 2:9", "연결점":"기둥같이 여기는 야고보와 게바와 요한도 내게 주신 은혜를 알므로 - 야고보의 교회 지도자 역할", "구분":"신약"},
        {"구절":"행 1:14", "연결점":"여자들과 예수의 모친 마리아와 예수의 아우들로 더불어 마음을 같이하여 전혀 기도에 힘쓰더라 - 부활 후 제자 공동체에 합류한 예수님의 형제들", "구분":"신약"},
        {"구절":"창 45:3-5", "연결점":"형제들이 요셉 앞에서 놀라므로 - 거부에서 화해로 가는 형제 관계의 변화", "구분":"구약"}
    ]
